#!/bin/bash
# CIFAR-10, ResNet-20: the extra-seed table completed to all 7 arms, seeds 1, 2. Writes to benchmarks/outputs/seeds/resnet20_cifar/seed<n>/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/train_seeds_resnet20_cifar.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=seeds_resnet20_cifar
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=02:10:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: MEASURED. 7 x T_diag x 2 seeds = 84.1 min of training, from the T_diag of the WALLTIME table above, plus the ~3 min of eval and setup a grouped job of this model measured end to end.
# Dataset: cifar10, read from $DATA_ROOT (default $SLURM_SUBMIT_DIR/dataset; an ImageNet job
# overrides it with the node-local copy it stages below). Compute nodes have no internet, and
# --no-allow-download turns a missing dataset into a clear error rather than a network timeout.

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"
DATA_ROOT="${DATA_ROOT:-$SLURM_SUBMIT_DIR/dataset}"

# Completes the extra-seed table for resnet20_cifar: all 7 arms, seeds 1, 2, one job.
#
# train_v0_seeds.sh ran two arms per (model, seed) -- diag and adamw. The other five arms existed
# at seed 0 only, so every comparison BETWEEN the five Fisher modes rested on a single draw. This
# job is the completion; see SEED_COMPLETION in benchmarks/slurm/generate_jobs.py for the
# per-model inventory it was written against.
#
# Protocol: identical to train_v0_seeds.sh, deliberately, so the runs join one set --
# --lr-schedule nominal, --reference-arm diag, --max-epoch-factor 3, the same checkpoint
# fractions, the bench's own nominal epoch count. Seed 0 is NOT one protocol (mlp_ln_mnist ran
# 'budget', the other four pre-date schedules.py), so read each run's own manifest.json before
# comparing a seed against it.
#
# diag and adamw ARE re-run: the reference arm derives the budget in-process, and a run directory
# should carry one report covering all of its arms. Both are bit-reproducible at a fixed seed under
# 'nominal', so this overwrite is idempotent -- and a disagreement would itself be a finding.
#
# Writes to benchmarks/outputs/seeds/resnet20_cifar/seed<n>/ -- ungrouped, its axis being the seed.
# One failing seed does not abort the rest; the job exits non-zero at the end if any failed.
FAILED=()
run_one () {  # $1 = seed
  echo "=== resnet20_cifar  seed $1 ==="
  python -m benchmarks.models.resnet20_cifar.bench \
    --arms diag kfac ekfac tkfac tekfac adam adamw \
    --seed "$1" \
    --budget-mode wct \
    --reference-arm diag \
    --max-epoch-factor 3 \
    --lr-schedule nominal \
    --num-workers 8 \
    --no-allow-download \
    --data-root "$DATA_ROOT" \
    --checkpoints 0,0.01,0.1,0.5,1 \
    --no-plot \
    --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/seeds/resnet20_cifar/seed$1" \
  || FAILED+=("resnet20_cifar:seed$1")
}

run_one 1
run_one 2
if [ ${#FAILED[@]} -gt 0 ]; then
  echo "FAILED runs: ${FAILED[*]}" >&2
  exit 1
fi
echo "all resnet20_cifar seed runs completed"
